def upd(r):
    k=r['stock_code']
    if k not in R: return
    lv,tot,pct,cum,dec=R[k]; v=rows[k]
    r['actual_close']=v['cl']
    base=f"收盤 {v['cl']}（今日 {v['chg']:+.2f}%，相對推薦價 {v['ret']:+.2f}%）；09-30 T86 {tot:+,} 張"
    if dec=='exit_pending':
        r['holding_status']=f"🛑 10-01 開盤出場（v8.3.3 待複核兩次皆成立）：第一次 12:30 {('9.8%' if k=='2886' else '6.3%')}、第二次盤後 14:33（09-29 T86 分子、avg_5day_volume 分母）{('9.8%' if k=='2886' else '6.3%')} 皆 ≥5% → 已決事項；09-30 T86 {tot:+,} 張＝{pct}%（{lv}）連續第二日賣超；{base}；入帳價用 10-01 收盤（v8.3.2）"
    elif dec=='exit':
        r['holding_status']=f"🛑 10-01 開盤出場（鐵律③ L4）：{base}＝{pct}%（≥8%，avg_5day_volume 分母、16:24 取樣），10 日累計 {cum} 為正但佔比 ≥8% 不受 v8.3.3 保護；入帳價用 10-01 收盤（v8.3.2）"
    elif dec=='pending':
        r['holding_status']=f"⚠️ 待複核（v8.3.3）：{base}＝{pct}%（<8%）且 10 日累計 {cum} 為正 → 10-01 不開盤出場，12:30 與盤後各複核一次，兩次皆 ≥5% 才於 10-02 開盤出場；距目標 740 僅 {v['dist_target']:.2f}%"
    else:
        r['holding_status']=f"續抱：{base}（{lv}），10 日累計 {cum}；鐵律①②③ 無觸發"
    r['reversal_level_0930t86']=lv
